# -*- coding: utf-8 -*-
"""Lecture 41 vignette pool A -- Inflammatory Lung Diseases: interstitial lung disease definition and causes,
presentation and workup, idiopathic interstitial pneumonia and pulmonary fibrosis, and connective tissue and
other unknown-cause disease (slides 3-38).

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.
EXPLANATIONS follow tools/question_writing/EXPLAIN_DEEP.md: the key names the decisive clue and the slide fact;
each wrong choice says why it fails for THIS patient, the replacing fact, and a "Tell:".

Narration scope (cms_e7l41_scope.py): drug causes come only from the short lists (s12 radiation, methotrexate,
amiodarone, nitrofurantoin, chemotherapeutics; s18 methotrexate; s72), never from the long s9 table alone; the
rare idiopathic subtypes (s38) are never keyed; one cytoplasmic antineutrophil cytoplasmic antibody pairing at most.
Conflicts held: connective tissue disease known versus unknown is never asked; "most common" is never keyed here;
"not infectious" (s3 against s16) is never used.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e7l41_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


def ORD(d, asc):
    d["ordered"] = True; d["asc"] = asc; return d


DEF = "Interstitial lung disease: definition and causes"
WRK = "Interstitial lung disease: presentation and workup"
IIP = "Idiopathic interstitial pneumonia and pulmonary fibrosis"
CTD = "Connective tissue and other unknown-cause disease"

